export function debounce(callback, delay) {
    let timer;
    const result = function (...args) {
        const context = this;
        clearTimeout(timer);
        timer = setTimeout(() => {
            callback.apply(context, args);
        }, delay);
    };
    result.reset = function (...args) {
        clearTimeout(timer);
        callback.apply(this, args);
    };
    return result;
}
